const T65=JSON.parse(require('fs').readFileSync('docs/prototypes/new-game/T65/board.json','utf8'));
// For each province, walk its polygon; for each shared edge, count the number of vertices it spans in T65
const key=(a,b)=>[JSON.stringify(a),JSON.stringify(b)].sort().join('|');
// Get 61 unique shared edges from T64
const t64Edges=new Map();
for(const p of T64.provinces){
  for(let j=0;j<p.polygon.length;j++){
    const a=p.polygon[j],b=p.polygon[(j+1)%p.polygon.length];
    const k=key(a,b);
    const owners=t64Edges.get(k)||[];
    owners.push(p.id);
    t64Edges.set(k,owners);
  }
}
const shared=[...t64Edges.entries()].filter(([_,o])=>o.length===2);
console.log('shared edges in T64:',shared.length);
// For each shared edge, find corresponding edge in T65 polygon for each owner
let bent=0,straight=0,odd=[];
for(const [k,o] of shared){
  const [a1,b1]=k.split('|').map(JSON.parse);
  const [pid1,pid2]=o;
  const p1=T65.provinces.find(p=>p.id===pid1),p2=T65.provinces.find(p=>p.id===pid2);
  let start1=-1,start2=-1;
  for(let j=0;j<p1.polygon.length;j++){
    const a=p1.polygon[j],b=p1.polygon[(j+1)%p1.polygon.length];
    if(JSON.stringify(a)===JSON.stringify(a1)&&JSON.stringify(b)===JSON.stringify(b1)){
      start1=j;break;
    }
  }
  for(let j=0;j<p2.polygon.length;j++){
    const a=p2.polygon[j],b=p2.polygon[(j+1)%p2.polygon.length];
    if(JSON.stringify(a)===JSON.stringify(a1)&&JSON.stringify(b)===JSON.stringify(b1)){
      start2=j;break;
    }
  }
  if(start1<0||start2<0){odd.push({pair:[pid1,pid2],start1,start2});continue;}
  // The curve is in T65 polygon; count vertices between start1 and (start1+1)
  // The 'edge' is a straight segment from a1->b1 in T64, but might be subdivided into multiple vertices in T65
  // Walk the polygon from a1 forward, count vertices before reaching b1
  let count1=0;
  for(let j=0;j<p1.polygon.length;j++){
    const v=p1.polygon[(start1+j)%p1.polygon.length];
    if(j===0&&JSON.stringify(v)!==JSON.stringify(a1)){console.log('not equal',pid1);break;}
    if(j>0&&JSON.stringify(v)===JSON.stringify(b1))break;
    count1++;
  }
  let count2=0;
  for(let j=0;j<p2.polygon.length;j++){
    const v=p2.polygon[(start2+j)%p2.polygon.length];
    if(j===0&&JSON.stringify(v)!==JSON.stringify(a1)){console.log('not equal',pid2);break;}
    if(j>0&&JSON.stringify(v)===JSON.stringify(b1))break;
    count2++;
  }
  if(count1>2||count2>2)bent++;
  else if(count1===2&&count2===2)straight++;
  else odd.push({pair:[pid1,pid2],count1,count2,start1,start2});
}
console.log('bent:',bent,'straight:',straight,'odd:',odd.length,odd.slice(0,3));
"

