// Independent bounded probe: shared curve reverse-orientation & vertex identity.
import fs from 'node:fs';
const T65=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T65/board.json','utf8'));
const key=(a,b)=>[JSON.stringify(a),JSON.stringify(b)].sort().join('|');

// 1. Check no polygon self-intersects (simple)
import {E,simple} from './docs/prototypes/new-game/T24/geometry.mjs';
const polyIssues=T65.provinces.filter(p=>!simple(p.polygon));
console.log('provinces with self-intersecting polygons:',polyIssues.length);
const isoIssues=T65.islands.filter(i=>!simple(i.polygon));
console.log('islands with self-intersecting polygons:',isoIssues.length);

// 2. For each shared edge in T65, walk each province's polygon. The shared 'curve' between A and B is the run of polygon edges that A and B share. They must have exactly the same vertex sequence in opposite order.
const t65Edges=new Map();
for(const p of T65.provinces){
  for(let j=0;j<p.polygon.length;j++){
    const a=p.polygon[j],b=p.polygon[(j+1)%p.polygon.length];
    const k=key(a,b);
    const owners=t65Edges.get(k)||[];
    owners.push({pid:p.id,dir:j});
    t65Edges.set(k,owners);
  }
}
const shared=[...t65Edges.entries()].filter(([_,o])=>o.length===2 && new Set(o.map(x=>x.pid)).size===2);
console.log('shared edges total:',shared.length);

let mismatched=0;
let mismatches=[];
for(const [k,o] of shared){
  const [pa,pb]=o;
  const polyA=T65.provinces.find(p=>p.id===pa.pid).polygon;
  const polyB=T65.provinces.find(p=>p.id===pb.pid).polygon;
  // Walk A's polygon starting at pa.dir, collecting vertices until we reach the B-direction.
  // Then walk B in the same 'directed' way, reverse.
  const seqA=[];
  for(let j=0;j<polyA.length;j++){
    seqA.push(polyA[(pa.dir+j)%polyA.length]);
    if(j>0 && JSON.stringify(polyA[(pa.dir+j)%polyA.length])===JSON.stringify(polyB[(pb.dir+1)%polyB.length])){
      break;
    }
  }
  // B's sequence is in reverse (the curve runs from A's start to B's end, opposite direction)
  const seqB=[];
  for(let j=0;j<polyB.length;j++){
    seqB.push(polyB[(pb.dir+j)%polyB.length]);
  }
  // Check reverse equality
  const revB=[...seqB].reverse();
  // We compare seqA (with last vertex = B's pb.dir+1 = B's first vertex) vs reverse of seqB
  // Actually both sequences should be equal
  const eq = JSON.stringify(seqA)===JSON.stringify(revB);
  if(!eq){
    mismatched++;
    if(mismatches.length<3)mismatches.push({pair:[pa.pid,pb.pid],lenA:seqA.length,lenB:seqB.length});
  }
}
console.log('mismatched curves (sequence != reverse of other):',mismatched,mismatches);
" 2>&1 | head -20

