// Actually: in T65 polygon for province p, the polygon edge (a->b) has key(a,b). For each polygon edge, find what T64 shared edge it lies on.
function edgeKey(t65a, t65b, t64sharedKeys){
  // The T65 polygon edge may not directly match any T64 shared edge key.
  // Find the T64 edge (e1,e2) such that t65a and t65b are both on the line segment e1->e2.
  for(const k of t64sharedKeys){
    const [e1,e2]=k.split('|').map(JSON.parse);
    // Collinear check + on-segment check
    const cross=(t65a[0]-e1[0])*(e2[1]-e1[1])-(t65a[1]-e1[1])*(e2[0]-e1[0]);
    const cross2=(t65b[0]-e1[0])*(e2[1]-e1[1])-(t65b[1]-e1[1])*(e2[0]-e1[0]);
    if(Math.abs(cross)<1e-4 && Math.abs(cross2)<1e-4){
      // collinear; on segment?
      const dxe=e2[0]-e1[0],dye=e2[1]-e1[1];
      const len2=dxe*dxe+dye*dye;
      const t1=((t65a[0]-e1[0])*dxe+(t65a[1]-e1[1])*dye)/len2;
      const t2=((t65b[0]-e1[0])*dxe+(t65b[1]-e1[1])*dye)/len2;
