function isOnLine(p, a, b, tol=1e-3){
  const dxe=b[0]-a[0],dye=b[1]-a[1];
  const len2=dxe*dxe+dye*dye;
  if(len2<1e-9)return Math.hypot(p[0]-a[0],p[1]-a[1])<tol;
  // Cross product distance
  const cross=Math.abs((p[0]-a[0])*dye-(p[1]-a[1])*dxe)/Math.sqrt(len2);
  return cross<tol;
}
function project(p,a,b){
  const dxe=b[0]-a[0],dye=b[1]-a[1];
  const len2=dxe*dxe+dye*dye;
  if(len2<1e-9)return 0;
  return ((p[0]-a[0])*dxe+(p[1]-a[1])*dye)/len2;
}

function walkCurve(polygon, startIdx, endVertex, lineA, lineB){
  const seq=[polygon[startIdx]];
  for(let j=1;j<polygon.length;j++){
    const next=polygon[(startIdx+j)%polygon.length];
    if(!isOnLine(next,lineA,lineB))break;
    seq.push(next);
    if(JSON.stringify(next)===JSON.stringify(endVertex))break;
  }
  return seq;
}

