import fs from 'node:fs';
const T64=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T64/board.json','utf8'));
const T65=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T65/board.json','utf8'));
const key=(a,b)=>[JSON.stringify(a),JSON.stringify(b)].sort().join('|');
// Build contact set: pairs of provinces that share an edge
const contactsT64=new Set();
for(const p of T64.provinces)for(let j=0;j<p.polygon.length;j++){
  const a=p.polygon[j],b=p.polygon[(j+1)%p.polygon.length];
  const k=key(a,b);
  if(!contactsT64.has(k))contactsT64.add(k);
}
const ownerT64=new Map();
for(const p of T64.provinces)for(let j=0;j<p.polygon.length;j++){
  const a=p.polygon[j],b=p.polygon[(j+1)%p.polygon.length];
  const k=key(a,b);
  const o=ownerT64.get(k)||new Set();
  o.add(p.id);
  ownerT64.set(k,o);
}
const sharedT64=new Map();
for(const [k,o] of ownerT64)if(o.size===2)sharedT64.set(k,[...o].sort());

const ownerT65=new Map();
for(const p of T65.provinces)for(let j=0;j<p.polygon.length;j++){
  const a=p.polygon[j],b=p.polygon[(j+1)%p.polygon.length];
  const k=key(a,b);
  const o=ownerT65.get(k)||new Set();
  o.add(p.id);
  ownerT65.set(k,o);
}
const sharedT65=new Map();
for(const [k,o] of ownerT65)if(o.size===2)sharedT65.set(k,[...o].sort());

// Compare as sets of pair-sets
const pairsA=new Set([...sharedT64.values()].map(o=>o.sort().join('|')));
const pairsB=new Set([...sharedT65.values()].map(o=>o.sort().join('|')));
console.log('T64 pair count:',pairsA.size,'T65 pair count:',pairsB.size);
console.log('Pairs equal:',JSON.stringify([...pairsA].sort())===JSON.stringify([...pairsB].sort()));

// Also compare borders list in each province
const bordersT64=new Map();
for(const p of T64.provinces)bordersT64.set(p.id,new Set(p.borders));
const bordersT65=new Map();
for(const p of T65.provinces)bordersT65.set(p.id,new Set(p.borders));
let borderDiff=0;
for(const [id,s] of bordersT64){
  const o=bordersT65.get(id);
  if(!o||s.size!==o.size||[...s].some(x=>!o.has(x))){borderDiff++;console.log('diff in',id,'T64:',[...s],'T65:',o?[...o]:null);}
}
console.log('border list differences:',borderDiff);
" 2>&1 | head -10

