import fs from 'node:fs';
const T64=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T64/board.json','utf8'));
const T65=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T65/board.json','utf8'));
const T63=JSON.parse(fs.readFileSync('docs/prototypes/new-game/T63/board.json','utf8'));
const T64provById=new Map(T64.provinces.map(p=>[p.id,p]));
const T63provById=new Map(T63.provinces.map(p=>[p.id,p]));
const T65provById=new Map(T65.provinces.map(p=>[p.id,p]));
console.log('T63 provinces:',T63.provinces.length,'T64:',T64.provinces.length,'T65:',T65.provinces.length);
// For T63 vs T65: compare labelAt (centered position)
let labelDiff=0;
const labelsDiff=[];
for(const p of T65.provinces){
 const t63=T63provById.get(p.id);
 if(!t63)continue;
 if(Math.abs(t63.labelAt[0]-p.labelAt[0])>0.001 || Math.abs(t63.labelAt[1]-p.labelAt[1])>0.001){
  labelDiff++;
  if(labelsDiff.length<3)labelsDiff.push({id:p.id,name:p.name,T63:t63.labelAt,T65:p.labelAt});
 }
}
console.log('labelAt differences T63 vs T65:',labelDiff,labelsDiff);
// For T64 vs T65: compare labelAt
let labelDiff64=0;
for(const p of T65.provinces){
 const t64=T64provById.get(p.id);
 if(!t64)continue;
 if(Math.abs(t64.labelAt[0]-p.labelAt[0])>0.001 || Math.abs(t64.labelAt[1]-p.labelAt[1])>0.001){labelDiff64++;}
}
console.log('labelAt differences T64 vs T65:',labelDiff64);
// T63 vs T65 - count polygons with same vertex count
let samePoly=0;
for(const p of T65.provinces){
 const t63=T63provById.get(p.id);
 if(!t63)continue;
 if(p.polygon.length===t63.polygon.length)samePoly++;
}
console.log('T65 provinces with same polygon vertex count as T63:',samePoly,'/',T65.provinces.length);
" 2>&1 | head -10

